      "id": "arxiv:2609.05232v1",
      "title": "Substrate-Aware AI Agents: Execution Context as a First-Class Input",
      "url": "https://arxiv.org/abs/2609.05232v1",
      "pdfUrl": "https://arxiv.org/pdf/2609.05232v1",
