      "id": "49587379",
      "title": "Cutting (Claude Code) token spend on dynamic workflows 80%",
      "url": "https://news.ycombinator.com/item?id=49587379",
      "hnUrl": "https://news.ycombinator.com/item?id=49587379",
      "source": "Hacker News",
      "points": 2,
